<html lang="en" data-bs-theme="dark"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Create Company - CoreLynk</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css" rel="stylesheet"><link href="<?= base_url('assets/css/auth-login.css') ?>" rel="stylesheet"></head>
<body><main class="auth-shell"><section class="auth-showcase"><div class="brand-lockup"><span class="brand-mark" aria-hidden="true"><span></span><span></span><span></span><span></span></span><span>CoreLynk</span></div><div class="showcase-copy"><span class="eyebrow"><i class="bi bi-building-add"></i> New workspace</span><h1>Keep businesses<br><span>separate.</span></h1><p>Your new company receives its own isolated database, users, permissions, inventory, and accounts.</p></div></section><section class="auth-panel"><div class="login-card"><header class="login-header"><span class="login-kicker">NEW COMPANY</span><h2>Create a company</h2></header><div class="login-body"><?php $validation = session('validation'); ?><?= form_open('/companies') ?><div class="field-group"><label class="cl-label" for="company_name">Company name</label><div class="input-shell"><i class="bi bi-building"></i><input class="form-control cl-input" id="company_name" name="company_name" value="<?= esc(old('company_name')) ?>" maxlength="150" required autofocus></div><?php if ($validation && $validation->hasError('company_name')): ?><div class="invalid-feedback d-block"><?= esc($validation->getError('company_name')) ?></div><?php endif; ?></div><button class="btn-signin" type="submit">Create isolated workspace</button><?= form_close() ?><div class="login-footer"><a href="<?= base_url('/companies') ?>"><i class="bi bi-arrow-left"></i> Back to companies</a></div></div></div></section></main></body></html>
